import{_ as e,o as t,c as r,a2 as s}from"./chunks/framework.kOe0DhAP.js";const _=JSON.parse('{"title":"交易规则","description":"先确定订单是否合法，再判断能否成交。","frontmatter":{"title":"交易规则","description":"先确定订单是否合法，再判断能否成交。"},"headers":[],"relativePath":"spot/rules.md","filePath":"spot/rules.md"}'),i={name:"spot/rules.md"};function o(l,a,d,n,p,c){return t(),r("div",null,[...a[0]||(a[0]=[s('<div class="doc-eyebrow">现货手册 / TGEX KNOWLEDGE BASE</div><h1 id="交易规则" tabindex="-1">交易规则 <a class="header-anchor" href="#交易规则" aria-label="Permalink to &quot;交易规则&quot;">​</a></h1><div class="doc-lead">先确定订单是否合法，再判断能否成交。</div><h2 id="pairs" tabindex="-1">币种与交易对 <a class="header-anchor" href="#pairs" aria-label="Permalink to &quot;币种与交易对 {#pairs}&quot;">​</a></h2><p>每个交易对需要定义基础币、计价币、交易状态与商户范围。只允许充值的币种不一定已开放交易，存在交易对记录也不代表处于可交易状态。</p><h2 id="types" tabindex="-1">订单类型 <a class="header-anchor" href="#types" aria-label="Permalink to &quot;订单类型 {#types}&quot;">​</a></h2><p>已检查的枚举包含限价单与市价单。限价买单约束最高买入价，限价卖单约束最低卖出价。市价单按可成交流动性执行，不承诺固定价格；买入以金额还是数量提交，应以实际版本规则为准。</p><h2 id="limits" tabindex="-1">精度、限额与手续费 <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;精度、限额与手续费 {#limits}&quot;">​</a></h2><p>价格精度、数量精度、最小数量和最小金额是不同约束。金额计算应使用明确的十进制精度与舍入规则，显示位数不能替代结算精度。</p><p>手续费需要说明费率来源、收取币种、收取时机和舍入方式。本文示例使用假设费率，实际费率由交易产品与商户配置决定。</p>',10)])])}const u=e(i,[["render",o]]);export{_ as __pageData,u as default};
